description:
Implement a `createValidated` function that wraps an object in a `Proxy` and throws a `TypeError` if a property is set to a value that fails its validator.

**Example:**
```js
const obj = createValidated(
  { age: 25 },
  { age: v => typeof v === 'number' && v >= 0 }
);
obj.age = 30;  // OK
obj.age = -1;  // throws TypeError
```

starter_code:
export function createValidated(target, validators) {
  // your code here
}

test_suite:
test('valid set passes', () => {
  const obj = createValidated({ age: 25 }, { age: v => v >= 0 });
  obj.age = 30;
  expect(obj.age).toBe(30);
});

test('invalid set throws TypeError', () => {
  const obj = createValidated({ age: 25 }, { age: v => v >= 0 });
  expect(() => { obj.age = -1; }).toThrow(TypeError);
});

test('unvalidated props can be set freely', () => {
  const obj = createValidated({ name: 'Alice' }, {});
  obj.name = 'Bob';
  expect(obj.name).toBe('Bob');
});

// __hidden__
test('get passes through correctly', () => {
  const obj = createValidated({ x: 42 }, {});
  expect(obj.x).toBe(42);
});

solution:
export function createValidated(target, validators) {
  return new Proxy(target, {
    set(obj, prop, value) {
      const validate = validators[prop];
      if (validate && !validate(value)) {
        throw new TypeError(`Invalid value for ${String(prop)}: ${value}`);
      }
      obj[prop] = value;
      return true;
    }
  });
}
